local records = {
    [17] = { en = "Draws on the soul of the party member to shield them, absorbing $?a14748[${$s1*(1+$14748s1/100)}][$s1] damage.  Lasts $d.  While the shield holds, spellcasting will not be interrupted by damage.  Once shielded, the target cannot be shielded again for $6788d.", description = "Attinge all’anima del membro del gruppo per proteggerlo, assorbendo $?a14748[${$s1*(1+$14748s1/100)}][$s1] danni.  Dura $d.  Finché lo scudo resiste, i danni non interrompono il lancio degli incantesimi.  Una volta protetto, il bersaglio non può ricevere un altro scudo per $6788d." },
    [71] = { en = "A defensive combat stance.  Decreases damage taken by $7376s1% and damage caused by $7376s2%.  Increases all threat generated by $?a12792[${($7376s3+100)*($12792s1/100+1)-100)}.1%][$7376s3%].", description = "Una posizione difensiva da combattimento.  Riduce i danni subiti del $7376s1% e i danni inflitti del $7376s2%.  Aumenta tutta la minaccia generata del $?a12792[${($7376s3+100)*($12792s1/100+1)-100)}.1%][$7376s3%]." },
    [100] = { en = "Charge an enemy, generate $/10;s2 Rage, and Stun it for $7922d.  Cannot be used in combat.", description = "Carica un nemico, genera $/10;s2 Furia e lo stordisce per $7922d.  Non può essere usato in combattimento." },
    [543] = { en = "Absorbs $s1 Fire damage$?s11094[ and grants a $s2% chance to reflect Fire spells and effects][].  Lasts $d.", description = "Assorbe $s1 danni da Fuoco$?s11094[ e conferisce una probabilità del $s2% di riflettere gli incantesimi e gli effetti di Fuoco][].  Dura $d." },
    [633] = { en = "Heals a friendly target for an amount equal to the Paladin's maximum health.  Drains all of the Paladin's remaining Mana when used, but does not interrupt Mana regeneration.", description = "Cura un bersaglio amico di una quantità pari alla salute massima del Paladino.  Quando viene usato, prosciuga tutto il Mana rimanente del Paladino, ma non interrompe la rigenerazione del Mana." },
    [759] = { en = "Conjures a mana agate that can be used to instantly restore $5405s1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea un'agata di mana che può essere usata per ripristinare istantaneamente $5405s1 mana.\r\n\r\nGli oggetti creati scompaiono se si rimane disconnessi per più di 15 minuti." },
    [768] = { en = "Shapeshift into cat form, increasing melee attack power by $3025s1 plus Agility.  Also protects the caster from Polymorph effects and allows the use of various cat abilities.\r\n\r\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", description = "Assume la forma felina, aumentando la potenza d'attacco in mischia di $3025s1 più l'Agilità.  Protegge inoltre l'incantatore dagli effetti di Polymorph e consente di usare varie abilità feline.\r\n\r\nIl mutamento di forma libera l'incantatore da Polymorph e dagli effetti che limitano il movimento." },
    [783] = { en = "Transforms the druid into a travel form, increasing movement speed by $5419s1%.  Also protects the caster from Polymorph effects.  Only useable outdoors.\r\n\r\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", description = "Trasforma il druido in forma da viaggio, aumentando la velocità di movimento del $5419s1%.  Protegge inoltre l'incantatore dagli effetti di Polymorph.  Utilizzabile solo all'aperto.\r\n\r\nIl mutamento di forma libera l'incantatore da Polymorph e dagli effetti che limitano il movimento." },
    [930] = { en = "Hurls a lightning bolt at the enemy, dealing $s1 Nature damage and then jumping to additional nearby enemies.  Each jump reduces the damage by $?a415096[20%][30%].  Affects $x1 total targets.", description = "Scaglia un fulmine contro il nemico, infliggendo $s1 danni da Natura per poi balzare su altri nemici vicini.  Ogni balzo riduce i danni del $?a415096[20%][30%].  Colpisce $x1 bersagli in totale." },
    [974] = { en = "Protects the target with an earthen shield, reducing casting or channeling time lost when damaged by $s2%  and causing attacks to heal the shielded target for $<heal>.  This effect can only occur once every few seconds.  $n charges.  Lasts $d.  Earth Shield can only be placed on one target at a time and only one Elemental Shield can be active on a target at a time.", description = "Protegge il bersaglio con uno scudo di terra, riducendo del $s2% il tempo di lancio o canalizzazione perso quando subisce danni e facendo sì che gli attacchi curino il bersaglio protetto di $<heal>.  Questo effetto può verificarsi solo una volta ogni pochi secondi.  $n cariche.  Dura $d.  Earth Shield può essere applicato a un solo bersaglio alla volta e su un bersaglio può essere attivo un solo Scudo Elementale alla volta." },
    [982] = { en = "Revive your pet, returning it to life with $s1% of its health.", description = "Rianima il tuo famiglio, riportandolo in vita con il $s1% della sua salute." },
    [1062] = { en = "Roots the target in place and causes $o2 Nature damage over $d.  Damage caused may interrupt the effect.  You may $?s17245[have up to ${$17245m1+1} $ltarget:targets;][only have 1 target] Rooted at a time.", description = "Radica il bersaglio sul posto e gli infligge $o2 danni da Natura nell'arco di $d.  I danni inflitti possono interrompere l'effetto.  Puoi $?s17245[avere fino a ${$17245m1+1} $lbersaglio radicato:bersagli radicati;][avere un solo bersaglio radicato] alla volta." },
    [1064] = { en = "Heals the friendly target for $s1, then jumps to heal additional nearby targets.  If cast on a party member, the heal will only jump to other party members.  Each jump is $?a415096[65%][50%] as effective as the previous target.  Heals $x1 total targets.", description = "Cura il bersaglio amico di $s1, poi balza per curare altri bersagli vicini.  Se lanciato su un membro del gruppo, la cura balzerà solo verso altri membri del gruppo.  Ogni balzo è efficace $?a415096[al 65%][al 50%] rispetto al bersaglio precedente.  Cura $x1 bersagli in totale." },
    [1079] = { en = "Finishing move that causes damage over time.  Damage increases per combo point and by your Attack Power:\r\n   1 point  : ${6*($m1+$b1)} damage over $d.\r\n   2 points: ${6*($m1+2*$b1)} damage over $d.\r\n   3 points: ${6*($m1+3*$b1)} damage over $d.\r\n   4 points: ${6*($m1+4*$b1)} damage over $d.\r\n   5 points: ${6*($m1+5*$b1)} damage over $d.", description = "Mossa risolutiva che infligge danni nel tempo.  I danni aumentano per ogni punto combo e in base alla potenza d'attacco:\r\n   1 punto  : ${6*($m1+$b1)} danni in $d.\r\n   2 punti: ${6*($m1+2*$b1)} danni in $d.\r\n   3 punti: ${6*($m1+3*$b1)} danni in $d.\r\n   4 punti: ${6*($m1+4*$b1)} danni in $d.\r\n   5 punti: ${6*($m1+5*$b1)} danni in $d." },
    [1329] = { en = "Instantly attacks with both weapons for $<percent>% weapon damage plus an additional $5374s1 with each weapon.  Damage is increased by 20% against Poisoned targets.  Awards 2 combo points.", description = "Attacca istantaneamente con entrambe le armi infliggendo il $<percent>% dei danni dell'arma più altri $5374s1 con ciascuna arma.  I danni aumentano del 20% contro i bersagli avvelenati.  Assegna 2 punti combo." },
    [1455] = { en = "Converts ${($m1+$SPI*1)*(1+$18182m1/100)} Health into ${($m1+$SPI*1)*(1+$18182m1/100)} Mana for you. Spirit increases the amount converted.", description = "Converte ${($m1+$SPI*1)*(1+$18182m1/100)} salute in ${($m1+$SPI*1)*(1+$18182m1/100)} mana per te. Lo Spirito aumenta la quantità convertita." },
    [1456] = { en = "Converts ${($m1+$SPI*1)*(1+$18182m1/100)} Health into ${($m1+$SPI*1)*(1+$18182m1/100)} Mana for you. Spirit increases the amount converted.", description = "Converte ${($m1+$SPI*1)*(1+$18182m1/100)} salute in ${($m1+$SPI*1)*(1+$18182m1/100)} mana per te. Lo Spirito aumenta la quantità convertita." },
    [1494] = { en = "Shows the location of all nearby beasts on the minimap.  Only one form of tracking can be active at a time.", description = "Mostra la posizione di tutte le bestie vicine sulla minimappa.  Può essere attiva una sola forma di tracciamento alla volta." },
    [1777] = { en = "Causes $s1 damage, stops your attack, and incapacitates the target for $d.  The target must be facing you.  Any damage taken will break the effect.  Awards $s2 combo $lpoint:points;.", description = "Infligge $s1 danni, interrompe il tuo attacco e rende incapacitato il bersaglio per $d.  Il bersaglio deve essere rivolto verso di te.  Qualsiasi danno subito interrompe l'effetto.  Assegna $s2 $lpunto:punti combo;." },
    [1943] = { en = "Finishing move that causes damage over time, increased by your Attack Power.  Lasts longer per combo point:\r\n   1 point  : ${($m1+$b1)*4} damage over 8 secs\r\n   2 points: ${($m1+$b1*2)*5} damage over 10 secs\r\n   3 points: ${($m1+$b1*3)*6} damage over 12 secs\r\n   4 points: ${($m1+$b1*4)*7} damage over 14 secs\r\n   5 points: ${($m1+$b1*5)*8} damage over 16 secs", description = "Mossa risolutiva che infligge danni nel tempo, aumentati dalla tua potenza d'attacco.  La durata aumenta per ogni punto combo:\r\n   1 punto  : ${($m1+$b1)*4} danni in 8 sec\r\n   2 punti: ${($m1+$b1*2)*5} danni in 10 sec\r\n   3 punti: ${($m1+$b1*3)*6} danni in 12 sec\r\n   4 punti: ${($m1+$b1*4)*7} danni in 14 sec\r\n   5 punti: ${($m1+$b1*5)*8} danni in 16 sec" },
