    [2643] = { en = "Fires several missiles, hitting $x1 targets. Multi-Shot shares its cooldown with Aimed Shot.", description = "Lancia diversi missili, colpendo $x1 bersagli. Multi-Shot condivide il tempo di recupero con Aimed Shot." },
