    [8629] = { en = "Causes $s1 damage, stops your attack, and incapacitates the target for $d.  The target must be facing you.  Any damage taken will break the effect.  Awards $s2 combo $lpoint:points;.", description = "Infligge $s1 danni, interrompe il tuo attacco e rende incapacitato il bersaglio per $d.  Il bersaglio deve essere rivolto verso di te.  Qualsiasi danno subito interrompe l'effetto.  Assegna $s2 $lpunto:punti combo;." },
    [8631] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [8632] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [8633] = { en = "Garrote the enemy, causing $o1 damage over $d, increased by your Attack Power.  Must be stealthed and behind the target.  Awards $s2 combo $lpoint:points;.", description = "Garrotta il nemico, infliggendo $o1 danni nel tempo per $d, aumentati dalla potenza d'attacco. Richiede furtività e di trovarsi alle spalle del bersaglio. Conferisce $s2 $lpunto:punti combo;." },
    [8681] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $8679h% chance of poisoning the enemy which instantly inflicts $8680s1 Nature damage.  $m3 charges.", description = "Ricopre un'arma con un veleno che dura ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $8679h% di avvelenare il nemico, infliggendo istantaneamente $8680s1 danni da Natura. $m3 cariche." },
    [8918] = { en = "Regenerates all nearby party members within $a yards for $?$p456322[${$m1*2}][$s1] every $t1 sec for $d.  Druid must channel to maintain the spell.", description = "Rigenera tutti i membri del gruppo vicini entro $a iarde di $? $p456322[${$m1*2}][$s1] ogni $t1 sec. per $d. Il Druido deve canalizzare per mantenere l'incantesimo." },
