    [10310] = { en = "Heals a friendly target for an amount equal to the Paladin's maximum health and restores $s2 of their mana.  Drains all of the Paladin's remaining Mana when used, but does not interrupt Mana regeneration.", description = "Cura un bersaglio amico di una quantità pari alla salute massima del Paladino e ripristina $s2 mana.  Quando viene usato, prosciuga tutto il Mana rimanente del Paladino, ma non interrompe la rigenerazione del Mana." },
    [10605] = { en = "Hurls a lightning bolt at the enemy, dealing $s1 Nature damage and then jumping to additional nearby enemies.  Each jump reduces the damage by $?a415096[20%][30%].  Affects $x1 total targets.", description = "Scaglia un fulmine contro il nemico, infliggendo $s1 danni da Natura per poi balzare su altri nemici vicini.  Ogni balzo riduce i danni del $?a415096[20%][30%].  Colpisce $x1 bersagli in totale." },
    [10622] = { en = "Heals the friendly target for $s1, then jumps to heal additional nearby targets.  If cast on a party member, the heal will only jump to other party members.  Each jump is $?a415096[65%][50%] as effective as the previous target.  Heals $x1 total targets.", description = "Cura il bersaglio amico di $s1, poi balza per curare altri bersagli vicini.  Se lanciato su un membro del gruppo, la cura balzerà solo verso altri membri del gruppo.  Ogni balzo è efficace $?a415096[al 65%][al 50%] rispetto al bersaglio precedente.  Cura $x1 bersagli in totale." },
    [10623] = { en = "Heals the friendly target for $s1, then jumps to heal additional nearby targets.  If cast on a party member, the heal will only jump to other party members.  Each jump is $?a415096[65%][50%] as effective as the previous target.  Heals $x1 total targets.", description = "Cura il bersaglio amico di $s1, poi balza per curare altri bersagli vicini.  Se lanciato su un membro del gruppo, la cura balzerà solo verso altri membri del gruppo.  Ogni balzo è efficace $?a415096[al 65%][al 50%] rispetto al bersaglio precedente.  Cura $x1 bersagli in totale." },
