    [11069] = { en = "Reduces the casting time of your Fireball and Frostfire Bolt spells by $/1000;S1 sec.", description = "Riduce di $/1000;S1 sec. il tempo di lancio degli incantesimi Palla di Fuoco e Dardo di Fuocogelo." },
    [11070] = { en = "Reduces the casting time of your Frostbolt spell by $/1000;S1 sec.", description = "Riduce di $/1000;S1 sec. il tempo di lancio dell'incantesimo Dardo di Gelo." },
    [11165] = { en = "Reduces the cooldown of your Frost Nova spell by $/1000;s1 sec.", description = "Riduce di $/1000;s1 sec. il tempo di recupero dell'incantesimo Nova Gelida." },
    [11213] = { en = "Gives you a $m1% chance of entering a Clearcasting state after any damage spell hits a target.  The Clearcasting state reduces the mana cost of your next damage spell by $/10;12536s1%.", description = "Hai una probabilità del $m1% di entrare in uno stato di Lancio gratuito dopo che un qualsiasi incantesimo che infligge danni colpisce un bersaglio. Lo stato di Lancio gratuito riduce del $/10;12536s1% il costo in mana del tuo prossimo incantesimo che infligge danni." },
