    [11273] = { en = "Finishing move that causes damage over time, increased by your Attack Power.  Lasts longer per combo point:\r\n   1 point  : ${($m1+$b1)*4} damage over 8 secs\r\n   2 points: ${($m1+$b1*2)*5} damage over 10 secs\r\n   3 points: ${($m1+$b1*3)*6} damage over 12 secs\r\n   4 points: ${($m1+$b1*4)*7} damage over 14 secs\r\n   5 points: ${($m1+$b1*5)*8} damage over 16 secs", description = "Mossa risolutiva che infligge danni nel tempo, aumentati dalla tua potenza d'attacco.  La durata aumenta per ogni punto combo:\r\n   1 punto  : ${($m1+$b1)*4} danni in 8 sec\r\n   2 punti: ${($m1+$b1*2)*5} danni in 10 sec\r\n   3 punti: ${($m1+$b1*3)*6} danni in 12 sec\r\n   4 punti: ${($m1+$b1*4)*7} danni in 14 sec\r\n   5 punti: ${($m1+$b1*5)*8} danni in 16 sec" },
