    [16958] = { en = "Gives you a $m1% chance to gain an additional $/10;16959s1 Rage any time you get a critical strike while in Bear Form or Dire Bear Form. In addition, your non-periodic critical strikes from Cat Form abilities that generate Combo Points have a $m2% chance to add an additional Combo Point.", description = "Ti dà una probabilità del $m1% di ottenere $/10;16959s1 punti Rabbia aggiuntivi ogni volta che metti a segno un colpo critico in Forma d'orso o Forma d'orso feroce. Inoltre, i tuoi colpi critici non periodici con le abilità in Forma felina che generano punti combo hanno una probabilità del $m2% di aggiungere un punto combo aggiuntivo." },
    [17056] = { en = "Gives you a $m1% chance to gain $/10;17057s1 Rage when you shapeshift into Bear Form or Dire Bear Form. When you shift into Cat Form, you will regain ${100*($m2/100)}% of the Energy you had when you were last in Cat Form, plus ${10*($m2/100)} Energy for each second you spent not in Bear Form, Cat Form, or Dire Bear Form, up to a maximum of ${100*($m2/100)} Energy.", description = "Ti dà una probabilità del $m1% di ottenere $/10;17057s1 punti Rabbia quando ti trasformi in Forma d'orso o Forma d'orso feroce. Quando ti trasformi in Forma felina, recuperi ${100*($m2/100)}% dell'Energia che avevi l'ultima volta che eri in Forma felina, più ${10*($m2/100)} punti Energia per ogni secondo trascorso senza essere in Forma d'orso, Forma felina o Forma d'orso feroce, fino a un massimo di ${100*($m2/100)} punti Energia." },
