    [25503] = { en = "Generates 20 rage over $d$?p456328[][, but reduces base armor by 27% in Bear Form and 16% in Dire Bear Form].  The druid is considered in combat for the duration.", description = "Genera 20 rabbia in $d$?p456328[][, ma riduce l'armatura base del 27% in Forma d'Orso e del 16% in Forma d'Orso Feroce]. Il druido è considerato in combattimento per tutta la durata." },
