    [31016] = { en = "Finishing move that causes damage per combo point, increased by Attack Power:\r\n   1 point  : ${$m1+(1*$b1*$<mult>)}-${$M1+(1*$b1*$<mult>)} damage\r\n   2 points: ${$m1+(2*$b1*$<mult>)}-${$M1+(2*$b1*$<mult>)} damage\r\n   3 points: ${$m1+(3*$b1*$<mult>)}-${$M1+(3*$b1*$<mult>)} damage\r\n   4 points: ${$m1+(4*$b1*$<mult>)}-${$M1+(4*$b1*$<mult>)} damage\r\n   5 points: ${$m1+(5*$b1*$<mult>)}-${$M1+(5*$b1*$<mult>)} damage", description = "Mossa risolutiva che infligge danni per ogni punto combo, aumentati dalla potenza d'attacco:\r\n   1 punto  : ${$m1+(1*$b1*$<mult>)}-${$M1+(1*$b1*$<mult>)} danni\r\n   2 punti: ${$m1+(2*$b1*$<mult>)}-${$M1+(2*$b1*$<mult>)} danni\r\n   3 punti: ${$m1+(3*$b1*$<mult>)}-${$M1+(3*$b1*$<mult>)} danni\r\n   4 punti: ${$m1+(4*$b1*$<mult>)}-${$M1+(4*$b1*$<mult>)} danni\r\n   5 punti: ${$m1+(5*$b1*$<mult>)}-${$M1+(5*$b1*$<mult>)} danni" },
    [33388] = { en = "Allows you to ride basic ground mounts that require a riding skill of 75.\r\n\r\nKnown abilities:$?s824[\r\n$@spellname824][]$?s18995[\r\n$@spellname18995][]$?s10907[\r\n$@spellname10907][]$?s826[\r\n$@spellname826][]$?s10861[\r\n$@spellname10861][]$?s828[\r\n$@spellname828][]$?s10906[\r\n$@spellname10906][]$?s825[\r\n$@spellname825][]$?s1285849[\r\n$@spellname1285849][]", description = "Ti consente di cavalcare cavalcature terrestri di base che richiedono abilità di equitazione pari a 75.\r\n\r\nAbilità conosciute:$?s824[\r\n$@spellname824][]$?s18995[\r\n$@spellname18995][]$?s10907[\r\n$@spellname10907][]$?s826[\r\n$@spellname826][]$?s10861[\r\n$@spellname10861][]$?s828[\r\n$@spellname828][]$?s10906[\r\n$@spellname10906][]$?s825[\r\n$@spellname825][]$?s1285849[\r\n$@spellname1285849][]" },
    [33391] = { en = "Allows you to ride swift ground mounts that require a riding skill of 150.\r\n\r\nKnown abilities:$?s824[\r\n$@spellname824][]$?s18995[\r\n$@spellname18995][]$?s10907[\r\n$@spellname10907][]$?s826[\r\n$@spellname826][]$?s10861[\r\n$@spellname10861][]$?s828[\r\n$@spellname828][]$?s10906[\r\n$@spellname10906][]$?s825[\r\n$@spellname825][]$?s1285849[\r\n$@spellname1285849][]", description = "Ti consente di cavalcare cavalcature terrestri rapide che richiedono abilità di equitazione pari a 150.\r\n\r\nAbilità conosciute:$?s824[\r\n$@spellname824][]$?s18995[\r\n$@spellname18995][]$?s10907[\r\n$@spellname10907][]$?s826[\r\n$@spellname826][]$?s10861[\r\n$@spellname10861][]$?s828[\r\n$@spellname828][]$?s10906[\r\n$@spellname10906][]$?s825[\r\n$@spellname825][]$?s1285849[\r\n$@spellname1285849][]" },
