    [370336] = { en = "Grants your offensive abilities a chance to summon a spore that affects nearby players with Fungal Bloom when killed. This effect lasts for $d.\r\n\r\n$@spellicon370337$@spellname370337 \r\n$@spellaura370337", description = "Conferisce alle tue abilità offensive la possibilità di evocare una spora che, quando viene uccisa, colpisce i giocatori vicini con Germinazione fungina. Questo effetto dura $d.\r\n\r\n$@spellicon370337$@spellname370337 \r\n$@spellaura370337" },
    [370541] = { en = "Teleport player to Naxxramas.", description = "Teletrasporta il giocatore a Naxxramas." },
    [370548] = { en = "$1 mana regen every 5 seconds.", description = "Rigenerazione di mana pari a $1 ogni 5 secondi." },
    [370550] = { en = "Attack power increased by $s1.\r\n", description = "Potenza d'attacco aumentata di $s1.\r\n" },
    [398196] = { en = "Draw your ranged weapon and fire a quick shot at an enemy, causing normal ranged weapon damage and reducing the target's movement speed by $s2% for $d. Awards $s3 combo $lpoint:points;.\r\n\r\nQuick Draw benefits from all talents and effects that trigger from or modify Sinister Strike.\r\n", description = "Estrai l'arma a distanza e sferra un colpo rapido contro un nemico, infliggendo i normali danni dell'arma a distanza e riducendo la velocità di movimento del bersaglio del $s2% per $d. Fornisce $s3 $lpunto:punti combo;.\r\n\r\nColpo rapido beneficia di tutti i talenti e gli effetti che si attivano con o modificano Assalto funesto.\r\n" },
    [398197] = { en = "Gain the Quick Draw ability:\r\n\r\n$@spellicon398196\r\n$@spelldesc398196", description = "Ottieni l'abilità Colpo rapido:\r\n\r\n$@spellicon398196\r\n$@spelldesc398196" },
    [399962] = { en = "Gain the Mutilate ability:\r\n\r\n$@spellicon399956\r\n$@spelldesc399956", description = "Ottieni l'abilità Mutilazione:\r\n\r\n$@spellicon399956\r\n$@spelldesc399956" },
    [399968] = { en = "Gain the Envenom ability:\r\n\r\n$@spellicon399963\r\n$@spelldesc399963", description = "Ottieni l'abilità Avvelenamento:\r\n\r\n$@spellicon399963\r\n$@spelldesc399963" },
    [399969] = { en = "Gain the Deadly Brew ability:\r\n\r\n$@spellicon399965\r\n$@spelldesc399965", description = "Ottieni l'abilità Infuso Mortale:\r\n\r\n$@spellicon399965\r\n$@spelldesc399965" },
    [399986] = { en = "Throw a shuriken at your enemy dealing damage equal to $s1% of your Attack Power, and also strike up to ${$x1-1} additional nearby targets. Awards $s2 combo $lpoint:points; per target hit.\r\n", description = "Lancia uno shuriken contro il nemico, infliggendo danni pari al $s1% della tua Potenza d'attacco, e colpisce anche fino a ${$x1-1} bersagli aggiuntivi vicini. Assegna $s2 $lpunto:punti combo; per ogni bersaglio colpito.\r\n" },
    [400009] = { en = "Ranged Finishing move that causes damage per combo point, increased by Attack Power, and Stuns the target:\r\n\r\n   1 point:   ${$m1/100*($<base>+$<percombo>)} to ${$M1/100*($<base>+$<percombo>)} damage, 1 sec Stun\r\n   2 points: ${$m1/100*($<base>+$<percombo>*2)} to ${$M1/100*($<base>+$<percombo>*2)} damage, 2 sec Stun\r\n   3 points: ${$m1/100*($<base>+$<percombo>*3)} to ${$M1/100*($<base>+$<percombo>*3)} damage, 3 sec Stun\r\n   4 points: ${$m1/100*($<base>+$<percombo>*4)} to ${$M1/100*($<base>+$<percombo>*4)} damage, 4 sec Stun\r\n   5 points: ${$m1/100*($<base>+$<percombo>*5)} to ${$M1/100*($<base>+$<percombo>*5)} damage, 5 sec Stun\r\n\r\nCooldown shared with Kidney Shot.", description = "Mossa finale a distanza che infligge danni per ogni punto combo, aumentati dalla Potenza d'attacco, e stordisce il bersaglio:\r\n\r\n   1 punto:   ${$m1/100*($<base>+$<percombo>)} - ${$M1/100*($<base>+$<percombo>)} danni, 1 sec di stordimento\r\n   2 punti: ${$m1/100*($<base>+$<percombo>*2)} - ${$M1/100*($<base>+$<percombo>*2)} danni, 2 sec di stordimento\r\n   3 punti: ${$m1/100*($<base>+$<percombo>*3)} - ${$M1/100*($<base>+$<percombo>*3)} danni, 3 sec di stordimento\r\n   4 punti: ${$m1/100*($<base>+$<percombo>*4)} - ${$M1/100*($<base>+$<percombo>*4)} danni, 4 sec di stordimento\r\n   5 punti: ${$m1/100*($<base>+$<percombo>*5)} - ${$M1/100*($<base>+$<percombo>*5)} danni, 5 sec di stordimento\r\n\r\nTempo di recupero condiviso con Colpo ai Reni." },
    [400014] = { en = "You take $s1% reduced Physical damage while Blade Dance is active, reduced by an additional 1% for every $s12 of your Defense skill beyond ${$PL*5}. Additionally, your chance to Dodge is multiplied by $s11%, you have $s3% reduced chance to be critically hit by melee attacks, you deal $s10% less damage, the threat generated by all your actions is massively increased, and your Feint ability is replaced with Tease, which Taunts the target to attack you.\r\n\r\n$@spellicon410412\r\n$@spelldesc410412", description = "Subisci il $s1% di danni fisici in meno mentre Danza delle Lame è attiva; il valore è ridotto di un ulteriore 1% ogni $s12 punti abilità in Difesa oltre ${$PL*5}. Inoltre, la tua probabilità di schivare è moltiplicata per $s11%, hai una probabilità del $s3% in meno di subire un colpo critico dagli attacchi in mischia, infliggi il $s10% di danni in meno, la minaccia generata da tutte le tue azioni è notevolmente aumentata e la tua abilità Finta viene sostituita da Provocazione, che provoca il bersaglio ad attaccarti.\r\n\r\n$@spellicon410412\r\n$@spelldesc410412" },
