    [400625] = { en = "Your non-periodic critical strikes with Fireball, Frostfire Bolt, Fire Blast, and Scorch grant Hot Streak for $400625d. Hot Streak reduces the cast time of Pyroblast by $400625s1%, stacking up to $400625s2 times.\r\n", description = "I tuoi colpi critici non periodici con Palla di Fuoco, Dardo di Fuocogelo, Esplosione di Fuoco e Incendio rapido attivano Incandescenza per $400625d. Incandescenza riduce il tempo di lancio di Pirosfera del $400625s1% e si accumula fino a $400625s2 volte.\r\n" },
    [401417] = { en = "Heals the target for ${$<healpower>*$m1/100*3} health over $d and applies Temporal Beacon for $400735s3 sec. \r\n\r\nTemporal Beacon\r\n$@spellicon400735\r\n$@spelldesc400735", description = "Cura il bersaglio di ${$<healpower>*$m1/100*3} salute in $d e applica Fenditura Temporale per $400735s3 sec.\r\n\r\nFenditura Temporale\r\n$@spellicon400735\r\n$@spelldesc400735" },
