    [403489] = { en = "Engrave your helm with the Endless Rage rune:\r\n\r\n$@spellicon403218\r\n$@spelldesc403218", description = "Incidi sul tuo elmo la runa di Endless Rage:\r\n\r\n$@spellicon403218\r\n$@spelldesc403218" },
    [403619] = { en = "Surrounds the caster with fel energy, increasing spell damage and healing by $s3 plus additional spell damage and healing equal to $s1% of your Spirit. In addition, you regain $s2% of your maximum health every 5 sec. Only one type of Armor spell can be active on the Warlock at any time.  Lasts $d.\r\n", description = "Avvolge l'incantatore di energia vile, aumentando i danni e le cure degli incantesimi di $s3, più danni e cure aggiuntivi pari al $s1% del tuo Spirito. Inoltre, recuperi il $s2% della tua salute massima ogni 5 s. Sullo Stregone può essere attivo un solo tipo di incantesimo Armatura alla volta.  Dura $d.\r\n" },
    [403789] = { en = "Transform into a Demon, increasing Armor by $403816s1%, Health by $403816s6%, reducing the chance you will be critically hit by $403816s2%, increasing your threat by $403816s3%, increasing mana gained from Life Tap by $403816s4%, but reducing all damage you deal by $403816s5%. Metamorphosis transforms the functionality of some abilities and grants new ones:\r\n\r\nSearing Pain: Now instant.\r\n\r\nShadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to $403835x1 nearby enemies, but has a $s6 sec cooldown.\r\n\r\nFear: Replaced with Menace.\r\n\r\n$@spellicon403828\r\n$@spelldesc403828\r\n\r\n\r\nDemon Charge\r\n\r\n$@spellicon412788\r\n$@spelldesc412788\r\n\r\n\r\nDemonic Howl\r\n\r\n$@spellicon412789\r\n$@spelldesc412789", description = "Ti trasformi in un Demone, aumentando l'Armatura del $403816s1%, la Salute del $403816s6%, riducendo la probabilità di subire un colpo critico del $403816s2%, aumentando la tua minaccia del $403816s3%, aumentando il mana ottenuto da Risucchio di Vita del $403816s4%, ma riducendo tutti i danni che infliggi del $403816s5%. Metamorfosi trasforma il funzionamento di alcune abilità e ne conferisce di nuove:\r\n\r\nDolore Bruciante: ora istantaneo.\r\n\r\nDardo d'Ombra: diventa Fendente d'Ombra, un attacco da mischia d'Ombra che colpisce fino a $403835x1 nemici vicini, ma ha un tempo di recupero di $s6 s.\r\n\r\nPaura: sostituita da Minaccia.\r\n\r\n$@spellicon403828\r\n$@spelldesc403828\r\n\r\n\r\nCarica Demoniaca\r\n\r\n$@spellicon412788\r\n$@spelldesc412788\r\n\r\n\r\nUlulato Demoniaco\r\n\r\n$@spellicon412789\r\n$@spelldesc412789" },
    [403816] = { en = "Transform into a Demon, increasing Armor by $s1%, reducing the chance you will be critically hit by $s2%, increasing your threat by $s3%, increasing mana gained from Life Tap by $s4%, and transforming the functionality of some of your abilities:\r\n\r\nSearing Pain: Now instant.\r\n\r\nShadow Bolt: Becomes Shadow Cleave, a Shadow melee attack that hits up to $s1 nearby enemies.\r\n\r\nCurse of Recklessness: Now also taunts your target to attack you for $d.\r\n\r\nHowl of Terror: Now also forces all nearby enemies to attack you for $d, but cooldown increased to 10 minutes.", description = "Ti trasformi in un Demone, aumentando l'Armatura del $s1%, riducendo la probabilità di subire un colpo critico del $s2%, aumentando la tua minaccia del $s3%, aumentando il mana ottenuto da Risucchio di Vita del $s4% e trasformando il funzionamento di alcune delle tue abilità:\r\n\r\nDolore Bruciante: ora istantaneo.\r\n\r\nDardo d'Ombra: diventa Fendente d'Ombra, un attacco da mischia d'Ombra che colpisce fino a $s1 nemici vicini.\r\n\r\nMaledizione dell'Imprudenza: ora provoca anche il bersaglio, costringendolo ad attaccarti per $d.\r\n\r\nUlulato del Terrore: ora costringe anche tutti i nemici vicini ad attaccarti per $d, ma il tempo di recupero aumenta a 10 min." },
    [403858] = { en = "Gain the Haunt ability:\r\n\r\n$@spellicon403501\r\n$@spelldesc403501", description = "Ottieni l'abilità Infestazione:\r\n\r\n$@spellicon403501\r\n$@spelldesc403501" },
