    [403919] = { en = "Engrave your gloves with the Haunt rune:\r\n\r\n$@spellicon403501\r\n$@spelldesc403501", description = "Incidi sui guanti la runa Infestazione:\r\n\r\n$@spellicon403501\r\n$@spelldesc403501" },
    [403920] = { en = "Engrave your cloak with the Soul Siphon rune:\r\n\r\n$@spellicon403511\r\n$@spelldesc403511", description = "Incidi sul mantello la runa Sifone dell'Anima:\r\n\r\n$@spellicon403511\r\n$@spelldesc403511" },
    [403925] = { en = "Engrave your gloves with the Chaos Bolt rune:\r\n\r\n$@spellicon403629\r\n$@spelldesc403629", description = "Incidi sui guanti la runa Dardo del Caos:\r\n\r\n$@spellicon403629\r\n$@spelldesc403629" },
    [403932] = { en = "Engrave your chest or robe with the Master Channeler rune:\r\n\r\n$@spellicon403668\r\n$@spelldesc403668", description = "Incidi sul torace o sulla veste la runa Canalizzatore Supremo:\r\n\r\n$@spellicon403668\r\n$@spelldesc403668" },
    [403936] = { en = "Engrave your gloves with the Shadow Bolt Volley rune:\r\n\r\n$@spellicon403628\r\n$@spelldesc403628", description = "Incidi sui guanti la runa Raffica di Dardi d'Ombra:\r\n\r\n$@spellicon403628\r\n$@spelldesc403628" },
    [403937] = { en = "Engrave your chest or robe with the Lake of Fire rune:\r\n\r\n$@spellicon403666\r\n$@spelldesc403666", description = "Incidi sul torace o sulla veste la runa Lago di Fuoco:\r\n\r\n$@spellicon403666\r\n$@spelldesc403666" },
    [403938] = { en = "Engrave your gloves with the Metamorphosis rune:\r\n\r\n$@spellicon403789\r\n$@spelldesc403789", description = "Incidi sui guanti la runa Metamorfosi:\r\n\r\n$@spellicon403789\r\n$@spelldesc403789" },
    [407627] = { en = "Increases the threat generated by your Holy spells by $s5% and gives you mana when healed by other friendly targets' spells equal to $s4% of the amount healed. Additionally, damage which takes you below $407627s6% health is reduced by $407627s7%. Lasts $d.\r\n", description = "Aumenta la minaccia generata dai tuoi incantesimi Sacri del $s5% e ti fornisce mana quando vieni curato dagli incantesimi di altri bersagli alleati, pari al $s4% della quantità curata. Inoltre, i danni che ti porterebbero sotto il $407627s6% di salute vengono ridotti del $407627s7%. Dura $d.\r\n" },
    [407788] = { en = "Increases all damage and healing caused by $s1% for $d.  Causes Forbearance and cannot be used while Forebearance is active.", description = "Aumenta tutti i danni e le cure inflitti del $s1% per $d.  Causa Indulgenza e non può essere usato mentre Indulgenza è attiva." },
    [407798] = { en = "Fills you with holy spirit for $d, causing each of your melee attacks to deal $407799s1% weapon damage to your target, but you lose health equal to $s4% of the damage inflicted. While this seal is active, your party and raid members within $407802a1 yards each gain mana equal to $s2% of damage you take from this seal.\r\n\r\n\r\nUnleashing this Seal's energy will judge an enemy, instantly causing $407803s1% weapon damage at the cost of health equal to $s4% of the damage inflicted.\r\n\r\nThis ability's Seal and Judgement benefit from talents and effects that modify the Seal or Judgement of Seal of Righteousness.", description = "Ti riempie di spirito sacro per $d, facendo sì che ciascuno dei tuoi attacchi in mischia infligga al bersaglio il $407799s1% dei danni dell'arma, ma perdi salute pari al $s4% dei danni inflitti. Mentre questo sigillo è attivo, i membri del tuo gruppo e della tua incursione entro $407802a1 m recuperano mana pari al $s2% dei danni che subisci a causa di questo sigillo.\r\n\r\n\r\nLiberare l'energia di questo Sigillo giudicherà un nemico, infliggendo istantaneamente il $407803s1% dei danni dell'arma al costo di salute pari al $s4% dei danni inflitti.\r\n\r\nIl Sigillo e il Giudizio di questa abilità beneficiano dei talenti e degli effetti che modificano il Sigillo o il Giudizio di Sigillo della Rettitudine." },
    [407804] = { en = "$s1% of all damage taken by party members within $a1 yards is redirected to the Paladin for $d. Damage which reduces the Paladin below $s2% health will break the effect and grant the paladin $407805s1% increased damage and healing done for $407805d. Divine Sacrifice cannot be used while you are under the effects of Blessing of Protection, Divine Shield, or Divine Protection, and prevents you from being targeted by those abilities while it is active.", description = "Il $s1% di tutti i danni subiti dai membri del gruppo entro $a1 m viene reindirizzato al Paladino per $d. I danni che portano il Paladino sotto il $s2% di salute interrompono l'effetto e gli conferiscono un aumento del $407805s1% ai danni e alle cure inflitti per $407805d. Sacrificio Divino non può essere usato mentre sei sotto gli effetti di Benedizione della Protezione, Scudo Divino o Protezione Divina e, finché è attivo, impedisce che tu venga scelto come bersaglio da tali abilità." },
    [407975] = { en = "Party members within $8514a1 yards gain increased combat ferocity.  Each melee hit has a $h% chance of granting the attacker an extra attack with $s1% additional Attack Power. No effect if the party member is already benefitting from Windfury Totem.\r\n", description = "I membri del gruppo entro $8514a1 m acquisiscono maggiore ferocia in combattimento.  Ogni colpo in mischia ha una probabilità del $h% di conferire all'attaccante un attacco extra con il $s1% di Potenza d'Attacco aggiuntiva. Non ha effetto se il membro del gruppo beneficia già del Totem della Furia del Vento.\r\n" },
    [407977] = { en = "While you are in Cat Form, Bear Form, or Dire Bear Form, party or raid members within $407975a1 yards gain increased combat ferocity.  Each melee hit has a $407975h% chance of granting the attacker an extra attack with $407975s1% additional Attack Power. No effect if the target is already benefitting from Windfury Totem.\r\n", description = "Quando sei in Forma Felina, Forma d'Orso o Forma d'Orso Tenebroso, i membri del gruppo o dell'incursione entro $407975a1 m acquisiscono maggiore ferocia in combattimento.  Ogni colpo in mischia ha una probabilità del $407975h% di conferire all'attaccante un attacco extra con il $407975s1% di Potenza d'Attacco aggiuntiva. Non ha effetto se il bersaglio beneficia già del Totem della Furia del Vento.\r\n" },
    [407988] = { en = "$?a768[|CFFFFFFFFRequires Cat Form|R][|CFFFF2020Requires Cat Form|R]\r\nFinishing move that increases Physical damage done by $s2% while in Cat Form.  Lasts longer per combo point:\r\n   1 point  : ${14+$<points>} seconds\r\n   2 points: ${19+$<points>} seconds\r\n   3 points: ${24+$<points>} seconds\r\n   4 points: ${29+$<points>} seconds\r\n   5 points: ${34+$<points>} seconds", description = "$?a768[|CFFFFFFFFRichiede Forma Felina|R][|CFFFF2020Richiede Forma Felina|R]\r\nMossa risolutiva che aumenta i danni fisici inflitti del $s2% in Forma Felina.  Dura più a lungo per ogni punto combo:\r\n   1 punto  : ${14+$<points>} secondi\r\n   2 punti: ${19+$<points>} secondi\r\n   3 punti: ${24+$<points>} secondi\r\n   4 punti: ${29+$<points>} secondi\r\n   5 punti: ${34+$<points>} secondi" },
    [408124] = { en = "Heals the target for ${$m1/100*7*$<healpower>} over $d.  When Lifebloom completes its duration or is dispelled, the target instantly heals for ${$m2/100*$<healpower>} and the Druid regains half the cost of the spell.  This effect can stack up to $u times on the same target.\r\n", description = "Cura il bersaglio di ${$m1/100*7*$<healpower>} in $d.  Quando Fioritura della Vita termina o viene dissolta, il bersaglio riceve istantaneamente una cura di ${$m2/100*$<healpower>} e il Druido recupera metà del costo dell'incantesimo.  Questo effetto può accumularsi fino a $u volte sullo stesso bersaglio.\r\n" },
    [408248] = { en = "Your Wrath spell reduces the cast time of your next $s3 Starfire spells by ${$m2/-1000}.2 sec. Stores up to $408255u charges. Lasts $408255d.", description = "La tua magia Ira riduce di ${$m2/-1000}.2 s il tempo di lancio delle prossime $s3 magie Fuoco stellare. Accumula fino a $408255u cariche. Dura $408255d." },
    [408438] = { en = "Gives your Lightning Bolt and Chain Lightning spells a $m1% chance to cast a second, similar spell on the same target at no additional cost that causes half damage and no threat.\r\n", description = "Le tue magie Dardo fulminante e Catena di fulmini hanno una probabilità del $m1% di lanciare una seconda magia simile sullo stesso bersaglio senza costi aggiuntivi, infliggendo metà dei danni e nessuna minaccia.\r\n" },
    [408514] = { en = "Protects the target with an earthen shield, reducing casting or channeling time lost when damaged by $s2%  and causing attacks to heal the shielded target for ${$m1*$<healpower>/100}.  This effect can only occur once every few seconds.  $n charges. Lasts $d.  Earth Shield can only be placed on one target at a time.\r\n", description = "Protegge il bersaglio con uno scudo terrestre, riducendo del $s2% il tempo di lancio o canalizzazione perso quando subisce danni e facendo sì che gli attacchi curino il bersaglio protetto di ${$m1*$<healpower>/100}. Questo effetto può verificarsi solo una volta ogni pochi secondi. $n cariche. Dura $d. Scudo terrestre può essere applicato a un solo bersaglio alla volta.\r\n" },
    [408524] = { en = "Each time you Block, you regenerate mana equal to $408525s2% of your maximum mana and you gain Armor equal to $408525s1% of your shield's armor value, stacking up to $s3 times. You also always gain $s1% increased chance to Block and $s2% increased Block value.\r\n\r\nIn addition, each time you use a Shock ability, you gain $460200s2 Spell Damage for each point of your defense skill beyond ${$PL*5}. Lasts $460171d.\r\n", description = "Ogni volta che blocchi, rigeneri mana pari al $408525s2% del tuo mana massimo e ottieni Armatura pari al $408525s1% del valore di armatura del tuo scudo, fino a un massimo di $s3 accumuli. Inoltre, ottieni sempre un aumento del $s1% alla probabilità di bloccare e del $s2% al valore di blocco.\r\n\r\nInoltre, ogni volta che usi un'abilità d'Urto, ottieni $460200s2 Danni magici per ogni punto della tua abilità di difesa oltre ${$PL*5}. Dura $460171d.\r\n" },
    [409163] = { en = "Engrave your belt with the Focused Rage rune:\r\n\r\n$@spellicon29787\r\n$@spelldesc29787", description = "Incidi la runa Furia concentrata sulla tua cintura:\r\n\r\n$@spellicon29787\r\n$@spelldesc29787" },
    [409239] = { en = "Instantly throw both weapons at all targets within $a1 yards, causing $s1% weapon damage.\r\n", description = "Scagli all'istante entrambe le armi contro tutti i bersagli entro $a1 metri, infliggendo il $s1% dei danni dell'arma.\r\n" },
    [409240] = { en = "Instantly throw both weapons at all targets within $a1 yards, causing ${$m1*1.5}% weapon damage with daggers, and $s1% weapon damage with all other weapons.\r\n", description = "Scagli all'istante entrambe le armi contro tutti i bersagli entro $a1 metri, infliggendo ${$m1*1.5}% dei danni dell'arma con i pugnali e il $s1% dei danni dell'arma con tutte le altre armi.\r\n" },
    [409805] = { en = "Gain the Wild Strikes ability:\r\n\r\n$@spellicon407977\r\n$@spelldesc407977", description = "Ottieni l'abilità Assalti selvaggi:\r\n\r\n$@spellicon407977\r\n$@spelldesc407977" },
    [409809] = { en = "Gain the Survival Instincts ability:\r\n\r\n$@spellicon408024\r\n$@spelldesc408024", description = "Ottieni l'abilità Istinti di sopravvivenza:\r\n\r\n$@spellicon408024\r\n$@spelldesc408024" },
