    [409819] = { en = "Gain the Savage Roar ability:\r\n\r\n$@spellicon407988\r\n$@spelldesc407988", description = "Ottieni l'abilità Ruggito selvaggio:\r\n\r\n$@spellicon407988\r\n$@spelldesc407988" },
    [409824] = { en = "Reduces the global cooldown on your  Rejuvenation and Lifebloom abilities by ${$m2/-1000}.1 sec and you gain the Lifebloom ability:\r\n\r\n$@spellicon408124\r\n$@spelldesc408124", description = "Riduce di ${$m2/-1000}.1 s il tempo di recupero globale delle tue abilità Ricrescita e Fioritura vitale e ottieni l'abilità Fioritura vitale:\r\n\r\n$@spellicon408124\r\n$@spelldesc408124" },
    [409826] = { en = "Gain the Nature's Fury ability:\r\n\r\n$@spellicon408307\r\n$@spelldesc408307", description = "Ottieni l'abilità Furia della natura:\r\n\r\n$@spellicon408307\r\n$@spelldesc408307" },
    [409828] = { en = "Gain the Mangle (Bear) ability and replace your Claw ability with Mangle (Cat). This ability benefits from and triggers all effects associated with Claw and Maul.\r\n\r\n$@spellicon407995\r\n$@spelldesc407995\r\n\r\n$@spellicon407993\r\n$@spelldesc407993\r\n", description = "Ottieni l'abilità Dilaniamento (Orso) e sostituisci l'abilità Artiglio con Dilaniamento (Felino). Questa abilità beneficia di tutti gli effetti associati ad Artiglio e Percossa e li attiva.\r\n\r\n$@spellicon407995\r\n$@spelldesc407995\r\n\r\n$@spellicon407993\r\n$@spelldesc407993\r\n" },
